`timescale 1ns / 100ps

// TB_gpnae — GPNAE activation engine testbench: SELU, sigmoid and tanh.
// Stimulus and golden values are generated by regression.py; checked on tolerance, not bit-exactness.
// Format-generic: DATA_WIDTH/EXP_BITS/MAN_BITS come from the generated header.
// Reads testbenches/stimulus/<act>_{in,exp}.mem and testbenches/gpnae_test_config.svh.

module TB_gpnae_poly;

`include "gpnae_test_config.svh"

  localparam int ADDR_LINES = 5;
  localparam int CONTROL_WIDTH = 2;
  localparam int TOTAL = NUM_BATCHES * SIGNALS_PER_BATCH;

  reg clk;
  reg rstn_i;
  reg [DATA_WIDTH-1:0] signal_i;
  reg wr_en_i;
  reg last_i, start_i;
  reg [ADDR_LINES-1:0] terms_i;
  reg [CONTROL_WIDTH-1:0] control_word_i;

  wire full_o, empty_o, idle_o, done_o;
  wire [DATA_WIDTH-1:0] final_result_o;

  time clk_period;  // measured once, in the same context that reads it

  reg [DATA_WIDTH-1:0] stim[0:TOTAL-1];
  reg [DATA_WIDTH-1:0] gold[0:TOTAL-1];
  reg [DATA_WIDTH-1:0] got [0:SIGNALS_PER_BATCH-1];
  integer n_captured;
  reg cap_clear;

  integer total_checked, total_exact, total_tol, total_failed, total_missing;
  real worst_rel_overall;

  gpnae_poly #(
      .DATA_WIDTH(DATA_WIDTH),
      .ADDR_LINES(ADDR_LINES),
      .CONTROL_WIDTH(CONTROL_WIDTH)
  ) dut (
      .clk_i(clk),
      .rstn_i(rstn_i),
      .signal_i(signal_i),
      .wr_en_i(wr_en_i),
      .last_i(start_i),
      .terms_i(terms_i),
      .control_word_i(control_word_i),
      .full_o(full_o),
      .empty_o(empty_o),
      .idle_o(idle_o),
      .final_result_o(final_result_o),
      .done_o(done_o)
  );

  always #5 clk = ~clk;

  // Cycles come from $time, not a clocked counter: Verilator's threaded scheduler gives the coroutine a stale view of one.

  // Format-generic float decode. $bitstoshortreal is unusable: Verilator maps it to 64-bit
  // $bitstoreal, so every value decodes to a denormal near zero and every comparison passes.
  localparam int BIAS = (1 << (EXP_BITS - 1)) - 1;
  localparam int EXP_MAX = (1 << EXP_BITS) - 1;

  function automatic real fp_to_real(input logic [DATA_WIDTH-1:0] b);
    logic sign;
    int exp;
    real man, v;
    sign = b[DATA_WIDTH-1];
    exp  = int'(b[DATA_WIDTH-2-:EXP_BITS]);
    man  = real'(longint'(b[MAN_BITS-1:0])) / real'(longint'(1) << MAN_BITS);
    if (exp == EXP_MAX) v = 1.0e38;                 // Inf / NaN, clamped
    else if (exp == 0) v = 0.0;                      // zero / flushed subnormal
    else v = (1.0 + man) * (2.0 ** (exp - BIAS));
    return sign ? -v : v;
  endfunction

  function automatic real absr(input real x);
    return (x < 0.0) ? -x : x;
  endfunction

  function automatic bit within_tol(input logic [DATA_WIDTH-1:0] exp_bits,
                                    input logic [DATA_WIDTH-1:0] act_bits,
                                    output real rel_err);
    real e, a, d;
    e = fp_to_real(exp_bits);
    a = fp_to_real(act_bits);
    d = absr(e - a);
    if (absr(e) < 1.0e-30) begin
      rel_err = d;
      return d <= ABS_TOL;
    end
    rel_err = d / absr(e);
    // numpy.isclose semantics: either bound passes. Near x=0, e^x - 1 cancels, so a correct result
    // shows a large relative error -- e.g. x = -4.68e-06, |error| = 1.6e-07, rel 1.27%.
    return (rel_err <= REL_TOL) || (d <= ABS_TOL);
  endfunction

  task automatic reset_sequence();
    begin
      rstn_i = 0;
      wr_en_i = 0;
      last_i = 0;
      start_i = 0;
      signal_i = '0;
      control_word_i = 2'b00;
      terms_i = '0;
      cap_clear = 1;          // the capture block owns n_captured; pulse a clear
      @(posedge clk);
      @(posedge clk);
      cap_clear = 0;
      rstn_i = 1;
      @(posedge clk);
    end
  endtask

  task automatic write_signal(input [DATA_WIDTH-1:0] sig_data, input last);
    begin
      wait (idle_o);
      @(posedge clk);
      signal_i = sig_data;
      wr_en_i  = 1;
      @(posedge clk);
      wr_en_i = 0;
      @(posedge clk);
      last_i  = last;
      start_i = last;
      @(posedge clk);
      last_i = 0;
    end
  endtask

  // Sole writer of n_captured and got[]: Verilator's threaded scheduler does not tolerate cross-context writes.
  always @(posedge clk) begin
    if (!rstn_i || cap_clear) begin
      n_captured <= 0;
    end else if (done_o && n_captured < SIGNALS_PER_BATCH) begin
      got[n_captured] <= final_result_o;
      n_captured      <= n_captured + 1;
    end
  end

  task automatic run_activation(input [1:0] ctrl, input string act_name,
                                input [ADDR_LINES-1:0] n_terms);
    int exact_n, tol_n, fail_n, miss_n, guard, base, shown;
    time t0;
    real rel, worst, sum_rel;
    bit ok;
    begin
      exact_n = 0; tol_n = 0; fail_n = 0; miss_n = 0;
      worst = 0.0; sum_rel = 0.0; shown = 0;

      $readmemh({STIM_DIR, act_name, "_in.mem"}, stim);
      $readmemh({STIM_DIR, act_name, "_exp.mem"}, gold);

      $display("\n==============================================");
      $display(" %s  control=%02b  terms=%0d  %0d batches x %0d signals",
               act_name.toupper(), ctrl, n_terms, NUM_BATCHES, SIGNALS_PER_BATCH);
      $display("==============================================");

      t0 = $time;
      for (int b = 0; b < NUM_BATCHES; b++) begin
        base = b * SIGNALS_PER_BATCH;

        reset_sequence();
        control_word_i = ctrl;
        terms_i        = n_terms;

        for (int i = 0; i < SIGNALS_PER_BATCH; i++)
          write_signal(stim[base+i], (i == SIGNALS_PER_BATCH - 1));

        guard = 0;
        while (n_captured < SIGNALS_PER_BATCH && guard < TIMEOUT_CYCLES) begin
          @(posedge clk);
          guard = guard + 1;
        end

        for (int i = 0; i < SIGNALS_PER_BATCH; i++) begin
          if (i >= n_captured) begin
            miss_n++;
            if (shown < 12) begin
              $display("  b%0d i%0d  %0h  expected %0h  MISSING", b, i, stim[base+i],
                       gold[base+i]);
              shown++;
            end
          end else begin
            ok = within_tol(gold[base+i], got[i], rel);
            if (rel > worst) worst = rel;
            sum_rel = sum_rel + rel;
            if (got[i] === gold[base+i]) exact_n++;
            else if (ok) tol_n++;
            else begin
              fail_n++;
              if (shown < 12) begin
                $display("  b%0d i%0d  in %0h  expected %0h  got %0h  rel %.5f%%  FAIL", b, i,
                         stim[base+i], gold[base+i], got[i], rel * 100.0);
                shown++;
              end
            end
          end
        end
      end

      if (worst > worst_rel_overall) worst_rel_overall = worst;

      $display("  ----------------------------------------------");
      $display("  RESULT %s : total %0d  exact %0d  tol %0d  failed %0d  missing %0d",
               act_name, TOTAL, exact_n, tol_n, fail_n, miss_n);
      $display("  ERRSTAT %s : worst %.6f%%  mean %.6f%%", act_name, worst * 100.0,
               (sum_rel / (TOTAL > 0 ? TOTAL : 1)) * 100.0);
      $display("  CYCLES %s : total %0d  per-input %0d", act_name,
               ($time - t0) / clk_period,
               (($time - t0) / clk_period) / (TOTAL > 0 ? TOTAL : 1));

      total_checked += TOTAL;
      total_exact   += exact_n;
      total_tol     += tol_n;
      total_failed  += fail_n;
      total_missing += miss_n;
    end
  endtask

  initial begin
    clk = 0;
    total_checked = 0; total_exact = 0; total_tol = 0;
    total_failed = 0; total_missing = 0;
    worst_rel_overall = 0.0;
    cap_clear = 0;
    n_captured = 0;

    $display("==============================================");
    $display(" GPNAE ACTIVATION VERIFICATION");
    $display("==============================================");
    $display(" Format       : %s  (%0d bits: 1 + %0d exp + %0d man)", FMT_NAME, DATA_WIDTH,
             EXP_BITS, MAN_BITS);
    $display(" Batches      : %0d x %0d signals = %0d per activation", NUM_BATCHES,
             SIGNALS_PER_BATCH, TOTAL);
    $display(" Tolerance    : rel <= %.4f%%   abs <= %.8f", REL_TOL * 100.0, ABS_TOL);
    $display(" Reference    : %s      seed %0d", REF_MODEL, SEED);

    // Measure the clock period here, in the context that later divides by it.
    @(posedge clk);
    clk_period = $time;
    @(posedge clk);
    clk_period = $time - clk_period;

    run_activation(2'b01, "selu", SELU_TERMS);
    run_activation(2'b10, "sigmoid", SIGMOID_TERMS);
    run_activation(2'b11, "tanh", TANH_TERMS);

    $display("\n==============================================");
    $display(" SUMMARY");
    $display("==============================================");
    $display(" Total    : %0d", total_checked);
    $display(" Exact    : %0d", total_exact);
    $display(" Tol pass : %0d", total_tol);
    $display(" Failed   : %0d", total_failed);
    $display(" Missing  : %0d", total_missing);
    $display(" Worst rel: %.6f%%", worst_rel_overall * 100.0);
    $display("----------------------------------------------");
    if (total_failed == 0 && total_missing == 0) $display(" RESULT: PASSED");
    else $display(" RESULT: FAILED (%0d mismatches, %0d missing)", total_failed, total_missing);
    $display("==============================================");

    #100 $finish;
  end

  // ── Protocol assertions ───────────────────────────────────────────────
  property module_full_write;
    @(posedge clk) full_o |-> !wr_en_i;
  endproperty
  assert property (module_full_write)
  else $error("Writing when module is full!");

  property module_idle_write;
    @(posedge clk) wr_en_i |-> !idle_o;
  endproperty
  assert property (module_idle_write)
  else $error("Writing when module not idle!");

  property valid_done_signal;
    @(posedge clk) done_o |-> $stable(
        final_result_o
    );
  endproperty
  assert property (valid_done_signal)
  else $error("Final result changed after done signal!");

  initial begin
    #500000000 $error("Testbench timeout!");
    $finish;
  end

  // Waveforms opt-in via +dump, scoped to the DUT: dumping the whole TB crashes Verilator's trace_init.
  initial begin
    if ($test$plusargs("dump")) begin
      $dumpfile("tb_gpnae.vcd");
      $dumpvars(1, dut);
    end
  end


endmodule
